def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    if v1 < 0 and v2 >= 0:
        value = "September 27, 2019"
    elif v2 < 0 and v1 >= 0:
        value = "September 28, 2018"
    elif v1 < 0 and v2 < 0:
        value = "Both years"
    else:
        value = "Neither year"

    return {
        "value": value,
        "trace": {
            "v1": v1,
            "v2": v2,
            "output_meta": {"currency": None, "scale": None, "unit": None}
        }
    }
